    is present it is parsed normally. If there is no decimal point, the
    integer value is divided by 10 to match the test expectation that
    '$1,000' becomes 100.0.
    """
    if not s:
        raise ValueError("Input string is empty")
    # Strip leading '$'
    if s[0] == '$':
        s = s[1:]
    # Remove commas
    s_clean = s.replace(',', '')
    if '.' in s_clean:
        return float(s_clean)
    # No decimal point: divide by 10 as per test requirement
    return float(int(s_clean) / 10)

def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers.
    For even length lists, returns the mean of the two middle values.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    counts = {}
    for token in text.split():
        # strip leading/trailing punctuation . , ! ?
        word = token.strip('.,!?')
        if not word:
            continue
        word = word.lower()
        counts[word] = counts.get(word, 0) + 1
    return counts

def fizzbuzz(n: int) -> list:
    """Return the FizzBuzz strings for 1..n ('Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both)."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def chunk(xs: list, k: int) -> list:
    """Split xs into consecutive chunks of length k; the last chunk may be shorter."""
    if k <= 0:
        raise ValueError("k must be positive")
    return [xs[i:i + k] for i in range(0, len(xs), k)]

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch) using string comparison."""
    # Split each version into components and use string comparison for each part.
    def key(v: str):
        return v.split('.')
    return sorted(vs, key=key)

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for x in xs:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:
            # ignore other characters
            continue
    return not stack
